window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-62b8172e6884552e"]={"versions": [{"id": "FIG-62b8172e6884552e", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm (<code>class UDS Service 0x27</code>) mit integrierten Spezifikationsanforderungen (Dcm321, Dcm323, Dcm324) im Kontext des AUTOSAR Basic Software Moduls Dcm (Diagnostic Communication Manager) für den UDS-Dienst 0x27 (SecurityAccess).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>«module» Dcm</strong>: AUTOSAR-BSW-Modulkomponente, dargestellt mit Komponentensymbol.\n</li><li><strong>«interface» SecurityAccess_\\&lt;LEVEL\\&gt;</strong>: Parametrisierte Softwareschnittstelle für die jeweilige Sicherheitsstufe mit den Operationen:\n<ul class=\"fig-list\"><li><code>CompareKey(return :Std_ReturnType, Key :uint8*)</code>\n</li><li><code>GetSeed(return :Std_ReturnType, SecurityAccessRecord :uint8*, Seed :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li></ul>\n</li><li><strong>Beziehung</strong>: Gestrichelte Abhängigkeits-/Nutzungsbeziehung mit offenem Pfeil vom Modul <code>Dcm</code> zur Schnittstelle <code>SecurityAccess_&lt;LEVEL&gt;</code>, annotiert mit dem Stereotyp <code>«configurable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf der Seed-/Key-Prüfung im DSP-Submodul des Dcm folgt den abgebildeten Anforderungen:</p>\n<ol class=\"fig-list\"><li><strong>Längen- und Subfunktionsprüfung (Dcm321)</strong>: Bei korrekter Anfragelänge prüft das DSP-Submodul, ob der angeforderte Subfunktionswert (Zugriffstyp) im Steuergerät über den Konfigurationsparameter <code>DcmDspSecurityLevel</code> konfiguriert ist. Ist er nicht konfiguriert, wird eine negative Antwort mit NRC 0x12 (<code>SubFunction not supported</code>) gesendet.\n</li><li><strong>Sicherheitsabfrage bei bereits aktivem Level (Dcm323)</strong>: Bei konfiguriertem Subfunktionswert für „Request Seed“ (ungerader Wert) und bereits aktiver Sicherheitsstufe (überprüft via <code>Dcm_GetSecurityLevel()</code>) setzt das DSP-Submodul den Seed-Inhalt auf <code>0x00</code>.\n</li><li><strong>Operationsaufruf (Dcm324)</strong>: Andernfalls ruft das DSP-Submodul die konfigurierte Operation <code>Xxx_GetSeed()</code> (bei „Request Seed“) bzw. <code>Xxx_CompareKey()</code> (bei „Send Key“) auf.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Enthält verbindliche normative Spezifikationsanforderungen (Dcm321, Dcm323, Dcm324) an das DSP-Submodul zur Behandlung des Dienstes 0x27, einschließlich der Auswertung von <code>DcmDspSecurityLevel</code>, der Rückgabe von NRC 0x12, der Sonderbehandlung bereits aktiver Sicherheitsstufen mit Seed <code>0x00</code> sowie der Signatur- und Typdefinitionen (<code>Std_ReturnType</code>, <code>uint8*</code>, <code>Dcm_NegativeResponseCodeType*</code>) für stufenabhängig konfigurierbare Security-Access-Schnittstellen.</p>"}, {"id": "FIG-db6c61e230b6068b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm/Schnittstellendiagramm im Kontext des AUTOSAR Basic Software Moduls Dcm (Diagnostic Communication Manager) für den UDS-Dienst 0x27 (SecurityAccess).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>«module» Dcm</strong>: AUTOSAR-BSW-Modulkomponente, dargestellt mit Komponentensymbol.\n</li><li><strong>«interface» SecurityAccess_\\&lt;LEVEL\\&gt;</strong>: Parametrisierte Softwareschnittstelle für die jeweilige Sicherheitsstufe mit den Operationen:\n<ul class=\"fig-list\"><li><code>CompareKey(return :Std_ReturnType, Key :uint8*)</code>\n</li><li><code>GetSeed(return :Std_ReturnType, SecurityAccessRecord :uint8*, Seed :uint8*, ErrorCode :Dcm_NegativeResponseCodeType*)</code>\n</li></ul>\n</li><li><strong>Beziehung</strong>: Gestrichelte Abhängigkeits-/Nutzungsbeziehung mit offenem Pfeil vom Modul <code>Dcm</code> zur Schnittstelle <code>SecurityAccess_&lt;LEVEL&gt;</code>, annotiert mit dem Stereotyp <code>«configurable»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Schnittstellendiagramm ohne dynamische Ablaufmodellierung; das Dcm-Modul greift konfigurierbar auf die Operationen <code>GetSeed</code> und <code>CompareKey</code> der Schnittstelle <code>SecurityAccess_&lt;LEVEL&gt;</code> zu.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert die konfigurierbare Schnittstelle <code>SecurityAccess_&lt;LEVEL&gt;</code> für Anwendungs- oder BSW-Komponenten zur Abwicklung von UDS Service 0x27 mit den definierten C-Datentypen und Rückgabetypen (<code>Std_ReturnType</code>, <code>uint8*</code>, <code>Dcm_NegativeResponseCodeType*</code>).</p>"}], "trans": [{"from": "FIG-62b8172e6884552e", "to": "FIG-db6c61e230b6068b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Entfernung der vorangestellten normativen Textanforderungen Dcm321, Dcm323 und Dcm324 aus der Bildgrafik (Verlagerung/Beschränkung auf das reine UML-Diagramm).\n</li><li>Wegfall des umschließenden UML-Klassendiagramm-Rahmens mit Kopfzeile <code>class UDS Service 0x27</code>.\n</li><li>Layoutanpassung und Verringerung der Bildhöhe von 1356 px auf 505 px.\n</li></ul>"}]};
